package android.text;
import java.util.ArrayList;
public class StaticLayout extends Layout {
    private final ArrayList<Integer> starts=new ArrayList<Integer>(); private final int lineHeight;
    public StaticLayout(CharSequence text,TextPaint paint,int width,Alignment alignment,float spacingMult,float spacingAdd,boolean includePad){super(text,paint,width,alignment,spacingMult,spacingAdd);lineHeight=Math.max(1,(int)(paint.getTextSize()*1.2f*spacingMult+spacingAdd));starts.add(Integer.valueOf(0));int start=0;float used=0;for(int i=0;i<text.length();i++){char c=text.charAt(i);float w=paint.measureText(text,i,i+1);if(c=='\n'){starts.add(Integer.valueOf(i+1));start=i+1;used=0;}else if(width>0 && used+w>width && i>start){starts.add(Integer.valueOf(i));start=i;used=w;}else used+=w;}}
    public int getLineCount(){return starts.size();} public int getLineStart(int line){return line==starts.size()?text.length():starts.get(line).intValue();} public int getLineTop(int line){return line*lineHeight;}
    public static final class Builder { private final CharSequence text; private final int start,end,width; private final TextPaint paint; private Alignment align=Alignment.ALIGN_NORMAL; private float mult=1,add; private boolean pad=true; private Builder(CharSequence t,int s,int e,TextPaint p,int w){text=t;start=s;end=e;paint=p;width=w;} public static Builder obtain(CharSequence t,int s,int e,TextPaint p,int w){return new Builder(t,s,e,p,w);} public Builder setAlignment(Alignment a){align=a;return this;} public Builder setIncludePad(boolean b){pad=b;return this;} public Builder setLineSpacing(float add,float mult){this.add=add;this.mult=mult;return this;} public Builder setMaxLines(int lines){return this;} public Builder setTextDirection(TextDirectionHeuristic h){return this;} public Builder setEllipsize(TextUtils.TruncateAt t){return this;} public Builder setEllipsizedWidth(int w){return this;} public Builder setBreakStrategy(int b){return this;} public Builder setHyphenationFrequency(int h){return this;} public StaticLayout build(){return new StaticLayout(text.subSequence(start,end),paint,width,align,mult,add,pad);} }
}
